.wpcf7 input[type="text"],
.wpcf7 input[type="email"],
.wpcf7 textarea
{
    background-color: #fff;
    color: #000;
    width: 90%;
}
  /* Fix per code inline */
code {
	font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
	background-color: #f0f0f0;
	padding: 2px 6px;
	border-radius: 4px;
	font-size: 0.9em;
	color: #d63384;
}

/* Code dentro pre (blocchi di codice) - non cambiare sfondo */
pre code {
	background-color: transparent;
	padding: 0;
	color: inherit;
}

.entry-content ul,
.wp-block-list {
	list-style-type: disc;
	margin-left: 1.9em;
	padding-left: 1em;
}

.entry-content ul li,
.wp-block-list li {
	list-style-type: disc;
}

